import java.util.*;

class Solution {
    private List<List<Integer>> out;
    private List<Integer> path;

    public List<List<Integer>> pathSum(TreeNode root, int target) {
        out = new ArrayList<>();
        path = new ArrayList<>();
        go(root, 0, target);
        return out;
    }

    private void go(TreeNode n, int sum, int target) {
        if (n == null) return;
        path.add(n.val);
        sum += n.val;
        if (n.left == null && n.right == null && sum == target)
            out.add(new ArrayList<>(path));   // save a copy, not the shared list
        go(n.left, sum, target);              // left first keeps left-to-right order
        go(n.right, sum, target);
        path.remove(path.size() - 1);         // backtrack
    }
}

