class Solution:
    def pathSum(self, root: Optional[TreeNode], target: int) -> List[List[int]]:
        out, path = [], []
        def go(n, s):
            if not n: return
            path.append(n.val); s += n.val
            if not n.left and not n.right and s == target: out.append(path[:])
            go(n.left, s); go(n.right, s)
            path.pop()
        go(root, 0)
        return out

