function pathSum(root, target) {
  const out = [];
  const go = (n, p, s) => {
    if (!n) return;
    const q = p.concat(n.val), t = s + n.val;
    if (!n.left && !n.right) { if (t === target) out.push(q); return; }
    go(n.left, q, t); go(n.right, q, t);
  };
  go(root, [], 0); return out;
}
